{"code": "async (page) => {
  // Check if the file exists and get its info
  const fs = require('fs');
  const path = require('path');

  const downloadPath = '<PROJECT_ROOT>/tmp/downloads';
  const files = fs.readdirSync(downloadPath);

  console.log('Files in downloads directory:');
  files.forEach(file => {
    const filePath = path.join(downloadPath, file);
    const stats = fs.statSync(filePath);
    console.log(`- ${file} (${stats.size} bytes)`);
  });

  // Check for the downloaded PDF
  const targetFile = 'ojsboss,+Journal+manager,+16_243-1254-2-PB.pdf';
  const targetPath = path.join(downloadPath, targetFile);

  if (fs.existsSync(targetPath)) {
    console.log(`\nFound target file: ${targetFile}`);
    console.log(`Size: ${fs.statSync(targetPath).size} bytes`);

    // Rename to a more descriptive name
    const newName = 'Can_Hiccup_Supply_Enough_Fish_to_Maintain_a_Dragons_Diet_University_of_Leicester.pdf';
    const newPath = path.join(downloadPath, newName);

    try {
      fs.renameSync(targetPath, newPath);
      console.log(`Renamed to: ${newName}`);
      return newPath;
    } catch (err) {
      console.log(`Error renaming: ${err.message}`);
      return targetPath;
    }
  } else {
    console.log('Target file not found');
    return null;
  }
}"}

